def convex_hull(points):
    hull = set()
    # sorted by increasing x, then y
    points = sorted(points, key=lambda p: (p[0], p[1]))
    # build lower hull
    for p in points:
        while len(hull) >= 2 and _turn(hull[-2], hull[-1], p) <= 0:
            hull.pop()
        hull.append(p)
    # build upper hull
    for p in reversed(points):
        while len(hull) >= 2 and _turn(hull[-2], hull[-1], p) <= 0:
            hull.pop()
        hull.append(p)
    # remove last element from result
    hull.pop()
    return list(hull)

def _turn(p1, p2, p3):
    return (p2[0] - p1[0]) * (p3[1] - p1[1]) - (p2[1] - p1[1]) * (p3[0] - p1[0])

