def evaluate_expression(variables, expression):
    legal_values = []

    for combination in range(2**len(variables)):
        values = []

        for i in range(len(variables)):
            if (combination >> i) & 1:
                values.append(True)
            else:
                values.append(False)

        result = evaluate(expression, values)
        if result:
            legal_values.append(tuple(values))

    return legal_values


def evaluate(expression, values):
    stack = []

    for token in expression:
        if token == '¬':
            operand = stack.pop()
            stack.append(not operand)
        elif token in ('and', 'or'):
            operand2 = stack.pop()
            operand1 = stack.pop()
            if token == 'and':
                stack.append(operand1 and operand2)
            else:
                stack.append(operand1 or operand2)
        else:
            stack.append(values[token])

    return stack.pop()


variables = ['x', 'y', 'z']
expression = ['x', 'y', '¬x']

legal_values = evaluate_expression(variables, expression)
print("The legal values of the boolean expression given the variables", variables, "and the expression", expression, "are", legal_values)

