def infix_to_postfix(expr: str) -> str:
    prec = {
        '^': 4,
        '*': 3,
        '/': 3,
        '+': 2,
        '-': 2,
        '(': 1
    }
    op_stack = []
    postfix = ''
    for c in expr: 
        if c in "ABCDEFGHIJKLMNOPQRSTUVWXYZ" or c in "0123456789": 
            postfix += c 
        elif c == '(': 
            op_stack.append(c) 
        elif c == ')': 
            while(op_stack[-1]!='('): 
                postfix += op_stack.pop() 
            op_stack.pop()
        else:
            while (len(op_stack) != 0 and prec[op_stack[-1]] >= prec[c]): 
                postfix += op_stack.pop() 
            op_stack.append(c) 
    while len(op_stack) != 0:
        postfix += op_stack.pop()
    return postfix

