def infix_to_postfix(expression):
    stack = []
    result_string = ""

    for char in expression:
        if char.isalnum():
            result_string += char
        elif char in ["+","-","*","/"]:
            while (len(stack) > 0 and stack[-1] != "(" and pemdas_of_operators(stack[-1], char)):
                result_string += stack.pop()
            stack.append(char)
        elif char == "(":
            stack.append(char)
        elif char == ")":
            while (len(stack) > 0 and stack[-1] != "("):
                result_string += stack.pop()
            stack.pop()

    while len(stack) > 0:
        result_string += stack.pop()

