def a_star_search(graph, start, goal):
    # Set up the open and closed sets
    open_set = [start]
    closed_set = []

    # Assign a cost of zero to the start node
    g_score = {start: 0}

    # Assign a heuristic estimate to reach the goal from the start
    h_score = {start: heuristic_estimate(start, goal)}

    # Initialize the f_score for the start node
    f_score = {start: h_score[start]}

    while open_set:
        # Find the node with the lowest f_score
        current = min(open_set, key=lambda node: f_score[node])

        if current == goal:
            return reconstruct_path(start, goal)

        open_set.remove(current)
        closed_set.append(current)

        for neighbor in graph[current]:
            if neighbor in closed_set:
                continue

            tentative_g_score = g_score[current] + distance(current, neighbor)

            if neighbor not in open_set or tentative_g_score < g_score[neighbor]:
                g_score[neighbor] = tentative_g_score
                h_score[neighbor] = heuristic_estimate(neighbor, goal)
                f_score[neighbor] = g_score[neighbor] + h_score[neighbor]

                if neighbor not in open_set:
                    open_set.append(neighbor)

    return None

def heuristic_estimate(node, goal):
    # Calculate the Manhattan distance between two nodes
    return abs(node.x - goal.x) + abs(node.y - goal.y)

def reconstruct_path(start, goal):
    # Reconstruct the path from the goal node to the start node
    path = [goal]
    current = goal

    while current != start:
        current = current.came_from
        path.append(current)

    return path[::-1]

