import random

def fitness(state):
    fitness = len(state)
    for row in range(len(state)-1):
        for col in range(row + 1, len(state)):
            if state[row] == state[col]:
                fitness -= 1
            elif abs(row - col) == abs(state[row] - state[col]):
                fitness -= 1
    return fitness

def create_initial_population(popsize, state_length):
    population = []
    while len(population) != popsize:
        indv = [random.randint(0, state_length-1) for i in range(state_length)]
        if indv not in population:
            population.append(indv)
    return population

def genetic_algorithm(popsize, mutation_rate, state_length):
    population = create_initial_population(popsize, state_length)
    best_fitness = 0
    best_state = None
    while best_fitness != state_length:
        fitscores = []
        for indv in population:
            fitscores.append(fitness(indv))
        index = fitscores.index(max(fitscores))
        best_fitness = fitscores[index]
        if best_fitness == state_length:
            best_state = population[index]
            break
        else:
            new_population = []
            while len(new_population) != popsize:
                dad = random.randint(0, popsize-1)
                mom = random.randint(0, popsize-1)
                if dad != mom:
                    child = crossover(population[dad], population[mom])
                    new_population.append(child)
            population = mutation(new_population, mutation_rate, state_length)
    return best_state

