def permutations(numbers):
  """
  This function takes in a list of numbers and returns all the possible permutations as a list of tuples.
  """
  if len(numbers) == 0:
    return []
  elif len(numbers) == 1:
    return [(numbers[0],)]
  else:
    result = []
    for i, num in enumerate(numbers):
      rest = numbers[:i] + numbers[i+1:]
      for permutation in permutations(rest):
        result.append((num,) + permutation)

    return result

