    def __init__(self): 
        self.board = board 
        self.player = 1

    def drawBoard(self): 
        for i in range(0, 3): 
            for j in range(0, 3): 
                print(self.board[i][j], end=" ") 
            print() 

    def checkStatus(self): 
        # check the rows 
        row_sum = [sum(row) for row in self.board] 
        if 3 in row_sum: 
            return 1
        elif -3 in row_sum: 
            return -1
        # check the columns 
        col_sum = [sum(col) for col in zip(*self.board)] 
        if 3 in col_sum: 
            return 1
        elif -3 in col_sum: 
            return -1
        # check the diagonals 
        if sum([self.board[i][i] for i in range(3)]) == 3: 
            return 1
        elif sum([self.board[i][i] for i in range(3)]) == -3: 
            return -1
        if sum([self.board[i][2 - i] for i in range(3)]) == 3: 
            return 1
        elif sum([self.board[i][2 - i] for i in range(3)]) == -3: 
            return -1
        # no winner yet    
        return 0

    def move(self): 
        row = int(input("Row (0, 1, 2) next move: ")) 
        col = int(input("Column (0, 1, 2) next move: ")) 
        # valid move check 
        if (row < 0 or row > 2) and (col < 0 or col > 2): 
            self.move() 
        else:    
            self.board[row][col] = self.player

        # check status of the game 
        status = self.checkStatus() 
        if status == 1: 
            print("Player 1 is the winner!") 
        elif status == -1: 
            print("Player 2 is the winner!") 
        elif status == -1: 
            print("It's a tie!") 
        else: 
            # First player 
            if self.player == 1: 
                self.player = -1
            # Second player 
            elif self.player == -1: 
                self.player = 1
            self.drawBoard() 
            self.move() 

