import nltk
from nltk.corpus import stopwords
from nltk.tokenize import word_tokenize, sent_tokenize
from nltk.stem import PorterStemmer

def text_summarizer(text):
    # Tokenize the text into sentences
    sentences = sent_tokenize(text)

    # Remove stopwords and punctuation, and stem the words
    stop_words = set(stopwords.words("english"))
    stemmer = PorterStemmer()

    frequency_table = {}
    for sentence in sentences:
        words = word_tokenize(sentence.lower())
        words = [stemmer.stem(word) for word in words if word.isalnum()]

        for word in words:
            if word in stop_words:
                continue
            if word in frequency_table:
                frequency_table[word] += 1
            else:
                frequency_table[word] = 1

    # Calculate the weighted frequency scores for each sentence
    sentence_scores = {}
    for sentence in sentences:
        words = word_tokenize(sentence.lower())
        words = [stemmer.stem(word) for word in words if word.isalnum()]

        for word in words:
            if word in stop_words:
                continue
            if sentence in sentence_scores:
                sentence_scores[sentence] += frequency_table[word]
            else:
                sentence_scores[sentence] = frequency_table[word]

    # Get the average sentence score
    sum_scores = 0
    for sentence in sentence_scores:
        sum_scores += sentence_scores[sentence]
    average_score = sum_scores / len(sentence_scores)

    # Generate the summary by selecting sentences with scores above the average
    summary = ""
    for sentence in sentences:
        if sentence in sentence_scores and sentence_scores[sentence] > average_score:
            summary += " " + sentence

    return summary

# Example usage
text_to_summarize = "Cats are social animals who form strong bonds with their owners and will vocalize, purr, knead, and head butt as part of their display of affection. They also have a curious nature, often exploring, climbing, and jumping around their environment."
summary = text_summarizer(text_to_summarize)
print(summary)

