class MaxHeap:
    def __init__(self, array):
        self.heap = self.build_heap(array)

    def build_heap(self, array):
        n = len(array)
        for i in reversed(range(n // 2)):
            self.heapify(i, array, n)
        return array

    def heapsort(self, array):
        n = len(array)
        for i in reversed(range(n)):
            array[i], array[0] = array[0], array[i]
            self.heapify(0, array, i)
        return array

    def heapify(self, current_index, array, heap_size):
        largest = current_index
        left_child = 2 * current_index + 1
        right_child = 2 * current_index + 2
        if left_child < heap_size and array[left_child] > array[largest]:
            largest = left_child
        if right_child < heap_size and array[right_child] > array[largest]:
            largest = right_child
        if largest != current_index:
            array[largest], array[current_index] = array[current_index], array[largest]
            self.heapify(largest, array, heap_size)

