    while queue: 
        r,c = queue.pop(0) 
        if (r,c) in visited: 
            continue 
        visited.add((r,c)) 
        if r > 0 and maze[r-1][c] != 0: # left 
            if (r-1,c) == destination: 
                path_length_so_far += 1 
                break 
            else: 
                queue.append((r-1,c)) 
        if r < len(maze)-1 and maze[r+1][c] != 0: # right 
            if (r+1,c) == destination: 
                path_length_so_far += 1
                break 
            else: 
                queue.append((r+1,c)) 
        if c > 0 and maze[r][c-1] != 0: # up 
            if (r,c-1) == destination: 
                path_length_so_far += 1
                break 
            else: 
                queue.append((r,c-1)) 
        if c < len(maze[0])-1 and maze[r][c+1] != 0: # down 
            if (r,c+1) == destination: 
                path_length_so_far += 1 
                break 
            else: 
                queue.append((r,c+1)) 
        path_length_so_far += 1 

    return path_length_so_far

