def infix_to_postfix(expression):
    operator_precedence = {'+': 1, '-': 1, '*': 2, '/': 2} # precedence mapping

    stack = []
    postfix = ''

    for char in expression:
        if char.isalnum():
            postfix += char
        elif char == '(':
            stack.append('(')
        elif char == ')':
            while stack and stack[-1] != '(':
                postfix += stack.pop()
            if stack and stack[-1] == '(':
                stack.pop()
        else:
            while stack and operator_precedence.get(char, 0) <= operator_precedence.get(stack[-1], 0):
                postfix += stack.pop()
            stack.append(char)

    while stack:
        postfix += stack.pop()

    return postfix

# Example usage:
