def levenshtein_distance(string1, string2):
    strings = [string1, string2]
    lens = [len(s) for s in strings]
    matrix = [[i+j for j in range(lens[1]+1)] for i in range(lens[0]+1)]

    for i in range(1, lens[0]+1):
        for j in range(1, lens[1]+1):
            if string1[i-1] == string2[j-1]:
                matrix[i][j] = matrix[i-1][j-1]
            else:
                matrix[i][j] = min(matrix[i-1][j] + 1, matrix[i][j-1] + 1, matrix[i-1][j-1] + 2)
    return matrix[lens[0]][lens[1]]

def fuzzy_search(string1, string2, max_distance):
    distance = levenshtein_distance(string1, string2)
    if distance <= max_distance:
        return True
    else:
        return False

