def construct_expression_tree(postfix):
    stack = []
    for char in postfix:
        if char.isalpha():
            stack.append(Node(char))
        elif char in ['+', '-', '*', '/']:
            temp = Node(char)
            temp.right = stack.pop()
            temp.left = stack.pop()
