O = 'O'
EMPTY = None
TIE = 'Tie'

class Board:
    def __init__(self):
        self.cells = []
        for i in range(BOARD_SIZE):
            row = [EMPTY] * BOARD_SIZE
            self.cells.append(row)

    def is_game_over(self):
        for row in self.cells:
            if row.count(X) == BOARD_SIZE:
                return X

        for row in self.cells:
            if row.count(O) == BOARD_SIZE:
                return O

        for row in self.cells:
            for val in row:
                if val == EMPTY:
                    return False

        return TIE

    def make_move(self, cell, player):
        self.cells[cell[0]][cell[1]] = player

class AI_Agent:
    def __init__(self, board, player):
        self.board = board
        self.player = player

    def move(self):
        return random.choice(self.calculate_valid_moves())

    def calculate_valid_moves(self):
        valid_moves = []
        for r in range(BOARD_SIZE):
            for c in range(BOARD_SIZE):
                if self.board.cells[r][c] == EMPTY:
                    valid_moves.append((r, c))
        return valid_moves

