# Define a function to build a frequency table
def build_frequency_table(s):
    table = {}
    for char in s:
        table[char] = table.get(char, 0) + 1
    return table

# Define a function to build a Huffman tree
def build_huffman_tree(frequency_table):
    tree = []
    for item, freq in frequency_table.items():
        tree.append((freq, item))
    tree.sort(reverse=True)
    while len(tree) > 1:
        f1, n1 = tree.pop()
        f2, n2 = tree.pop()
        tree.append((f1+f2, (n1, n2)))
        tree.sort(reverse=True)
    return tree[0]

# Define a function to generate Huffman codes
def generate_huffman_codes(tree):
    codes = {}
    for item in tree[1]:
        if type(item) == str:
            codes[item] = ''
        else:
            code_left, code_right = generate_huffman_codes(item)
            for key in code_left.keys():
                codes[key] = '0' + code_left[key]
            for key in code_right.keys():
                codes[key] = '1' + code_right[key]
    return codes

# Define a function to compress a string
def compress_string(s):
    # Build frequency table
    frequency_table = build_frequency_table(s)
    # Build Huffman tree
    tree = build_huffman_tree(frequency_table)
    # Generate Huffman codes
    codes = generate_huffman_codes(tree)
    # Create the encoded string
    encoded_string = ''
    for char in s:
        encoded_string += codes[char]
    # Return the encoded string
    return encoded_string

