class Trie:
    def __init__(self):
        self.root = self.get_node()

    def get_node(self):
        return TrieNode()

    def _char_to_index(self, ch):
        return ord(ch) - ord('a')

    def insert(self, key):
        node = self.root

        for level in range(len(key)):
            index = self._char_to_index(key[level])

            if not node.children[index]:
                node.children[index] = self.get_node()
            node = node.children[index]

