def infix_to_postfix(expression):
    """
    Converts an infix expression to a postfix expression.

    Parameters
    ----------
    expression : str
        The infix expression to convert.

    Returns
    -------
    str
        The postfix expression.
    """
    operators = {'+': 0, '-': 0, '*': 1, '/': 1, '^': 2}
    stack = []
    postfix = []

    for c in expression:
        if c in operators.keys():
            while stack and operators[c] <= operators[stack[-1]]:
                postfix.append(stack.pop())
            stack.append(c)
        elif c == '(':
            stack.append(c)
        elif c == ')':
            while stack[-1] != '(':
                postfix.append(stack.pop())
            stack.pop()
        else:
            postfix.append(c)

    while stack:
        postfix.append(stack.pop())

    return ''.join(postfix)

