class DiskTreeNode:
    def __init__(self):
        self.keys = []
        self.children = []
        self.min_keys = 2
        self.max_keys = 3

    def is_full(self):
        return len(self.keys) == self.max_keys

    def is_droop(self):
        return len(self.keys) < self.min_keys

    def insert(self, key, disk_num):
        # insert into the node
        self.keys.append((key, disk_num))
        self.keys.sort()

        # split the node into two nodes if it is full
        if self.is_full():
            node_one, node_two = self.split()
            return node_one, node_two
        else:
            return None, None

    def split(self):
        # get the middle key
        mid_key = self.keys[len(self.keys) // 2]

        # create two new nodes
        node_one = DiskTreeNode()
        node_two = DiskTreeNode()

        # add all keys before the mid_key to node_one
        for key in self.keys[:len(self.keys) // 2]:
            node_one.keys.append(key)

        # add all keys after the mid_key to node_two
        for key in self.keys[len(self.keys) // 2+1:]:
            node_two.keys.append(key)

        # return the two nodes
        return node_one, node_two

    def search(self, key):
        for i, (k, d) in enumerate(self.keys):
            if k > key:
                if self.children:
                    return self.children[i].search(key, disk_num)
                else:
                    return None, None
            elif k == key:
                return k, d
        if self.children:
            return self.children[-1].search(key, disk_num)
        else:
            return None, None

