def infix_to_postfix(infix_expr):
    PRECEDENCE = {'+':1, '-':1, '*':2, '/':2, '^':3} 
    operators = []
    output = ""

    for char in infix_expr:
        if char.isalpha():
            output += char
        elif char == '(':
            operators.append(char)
        elif char == ')':
            while len(operators) and operators[-1] != '(':
                output += operators.pop()
            operators.pop()
        else:
            while len(operators) and PRECEDENCE[char] <= PRECEDENCE[operators[-1]]:
                output += operators.pop()
            operators.append(char)

    while len(operators):
        output += operators.pop()
    return output

