def is_prime(n):
    # check cache
    if str(n) in is_prime.cache:
        return is_prime.cache[str(n)]

    # compute is_prime if number not in cache
    if n <= 1:
        is_prime.cache[str(n)] = False
    else:
        for x in range(2, int(n ** 0.5) + 1):
            if n % x == 0:
                is_prime.cache[str(n)] = False
                return False
        is_prime.cache[str(n)] = True
    return True

