def findSubArray(arr, n, givenSum): 
    subset = [0]* n; 
    if findPartitionRec(arr, subset, 0, n-1, 0, givenSum) == False: 
        print("No subset found")  
    else: 
        for i in range(n): 
            if subset[i] == 1: 
                print(arr[i], end = " "); 

def findPartitionRec(arr, subset, i, n, curSum, givenSum): 
    if curSum == givenSum: 
        return True
    if i == n: 
        return False
    subset[i] =  1
    if findPartitionRec(arr, subset, i + 1, n, curSum + arr[i], givenSum) == True: 
        return True
    subset[i] = 0
    if findPartitionRec(arr, subset, i + 1, n, curSum, givenSum) == True: 
        return True
    return False

if __name__ == "__main__": 
    arr = [2, 3, 7, 8, 10] 
    sum = 11    
    n = len(arr) 
