    for word, tag in pos_tags:
        if tag.startswith('DT'):
            categorized_text.append(f"{word}: Determiner, DT")
        elif tag.startswith('JJ'):
            categorized_text.append(f"{word}: Adjective, JJ")
        elif tag.startswith('NN'):
            categorized_text.append(f"{word}: Noun, NN")
        elif tag.startswith('VB'):
            categorized_text.append(f"{word}: Verb, VBD")
        elif tag.startswith('IN'):
            categorized_text.append(f"{word}: Preposition, IN")
        elif tag.startswith('NNP'):
            categorized_text.append(f"{word}: Proper Noun, NNP")
        elif tag.startswith('RB'):
            categorized_text.append(f"{word}: Adverb, RB")

