    board = init_board()
    players_mark = int(input("Choose 'X' or 'O': "))
    if players_mark == 1:
        ai_mark = 2
    else:
        ai_mark = 1
    print("1 stands for 'X' mark, 2 stands for 'O' mark.")
    print("Player starts first.")

    while move_possible(board):
        print_board(board)
        player_turn(board, players_mark, ai_mark)

run()

