def LCS(str1, str2):
    matrix = [[0 for x in range(len(str2)+1)] for y in range(len(str1)+1)]

    # Calculate the lengths of the longest common sequences
    # by comparing characters in both strings
    for i in range(len(str1)):
        for j in range(len(str2)):
            if str1[i] == str2[j]:
                matrix[i+1][j+1] = matrix[i][j] + 1
            else:
                matrix[i+1][j+1] = max(matrix[i][j+1], matrix[i+1][j])

    # Trace the LCS from the matrix
    common_sequence = []
    i = len(str1)
    j = len(str2)
    while i > 0 and j > 0:
        if str1[i-1] == str2[j-1]:
            common_sequence.append(str1[i-1])
            i -= 1
            j -= 1
        elif matrix[i-1][j] > matrix[i][j-1]:
            i -= 1
        else:
            j -= 1

    # Reverse the LCS
    common_sequence.reverse()

    return ''.join(common_sequence)

