def solveMaze(graph, source):

  # Create an array to store solution matrix 
  solution = [[0 for j in range(len(graph))] for i in range(len(graph))]

  if solveMazeUtil(graph, source, solution) == False:
    print('Solution does not exist')
  else:
    for i in range(len(graph)):
      print(solution[i])

def solveMazeUtil(graph, currentNode, solution): 
    # an array of 4 rows and 2 columns 
    dir = [[0, 1], [1, 0], [0, -1], [-1, 0]] 
    # source is reached 
    if currentNode == len(graph)-1: 
        solution[currentNode][0] = 1
        return True

    # try all 4 directions 
    for i in range(4): 
        row = currentNode + dir[i][0] 
        col = 0 + dir[i][1] 

        if row>=0 and row <len(graph) and col >= 0 and col < len(graph):  
            if graph[row][0] and solution[row][col] == 0: 
                solution[row][col] = 1

                if solveMazeUtil(graph, src, solution): 
                    return True

                    # Backtracking 
                    solution[row][col] = 0

    return False

