class Node: 
	def __init__(self, key, frequency): 
		self.keys = key 
		self.frequency = frequency 
		self.left = None
		self.right = None 

def find_optimal_tree(keys, frequency): 
	n = len(keys) 
	freq = [[0 for i in range(n)] for j in range(n)] 

	for i in range(n): 
		freq[i][i] = frequency[i] 

	for L in range(2, n+1): 
		for i in range(n-L+1): 
			j = i + L - 1
			freq[i][j] = float('inf') 
			sum_freq = 0
			for k in range(i, j+1): 
				sum_freq += frequency[k] 
			for r in range(i, j+1): 
				val = 0
				if r > i:
					val = freq[i][r-1] 
				if r < j: 
					val += freq[r+1][j] 
				if val < freq[i][j]: 
					freq[i][j] = val 
				freq[i][j] += sum_freq 

	return build_optimal_tree(freq, 0, n-1, keys) 

def build_optimal_tree(freq, i, j, keys): 
	if j < i: 
		return None

	root = Node(keys[i], freq[i][j]) 

	if j > i: 
		pos = find_index(freq, i, j) 
		root.left = build_optimal_tree(freq, i, pos-1, keys) 
		root.right = build_optimal_tree(freq, pos+1, j, keys) 

	return root 

def find_index(freq, i, j): 
	minimum = float('inf') 

	for k in range(i, j+1): 
		if freq[i][k-1] + freq[k+1][j] < minimum: 
			minimum = freq[i][k-1] + freq[k+1][j] 
			pos = k 

	return pos 

optimal_tree = find_optimal_tree(keys, frequency)

