def search_element(root, element):
    '''This function searches an element in a binary search tree. It returns True if the element is found and False otherwise.'''
    # base case
    if root == None or root.element == element:
        return root != None
    # If element to be searched is lesser than root's element,
    # then the element is present in the left subtree
    if element < root.element:
        return search_element(root.left, element)
    # Else the element is present in the right subtree
    else:
        return search_element(root.right, element)

