class HashMap:
    def __init__(self):
        self.size = 1000  # Adjust the size based on the expected number of elements
        self.buckets = [[] for _ in range(self.size)]

    def _hash(self, key):
        return hash(key) % self.size

    def insert(self, key, value):
        bucket = self._hash(key)
        for i, (k, v) in enumerate(self.buckets[bucket]):
            if k == key:
                self.buckets[bucket][i] = (key, value)  # Update existing key-value pair
                return
        self.buckets[bucket].append((key, value))  # Add new key-value pair

    def get(self, key):
        bucket = self._hash(key)
        for k, v in self.buckets[bucket]:
            if k == key:
                return v

    def delete(self, key):
        bucket = self._hash(key)
        for i, (k, v) in enumerate(self.buckets[bucket]):
            if k == key:
                del self.buckets[bucket][i]  # Delete key-value pair
                return

# Usage example
