import operator

def rpn_calculator():
    while True:
        expression = input('Enter expression in postfix notation, e.g "3 4 +": ')
        if expression == 'quit':
            break
        result = calculate(expression)
        if result is not None:
            print('Result:', result)
        else:
            print('Invalid input!')

def calculate(expression):
    stack = []
    operators = {'+': operator.add, '-': operator.sub, '*': operator.mul, '/': operator.truediv}
    for item in expression.split():
        if item in operators:
            try:
                op2 = stack.pop()
                op1 = stack.pop()
                result = operators[item](op1, op2)
            except IndexError:
                return None
            stack.append(result)
        else:
            stack.append(float(item))
    if len(stack) != 1:
        return None
    return stack.pop()

