def find_peak(arr):
    n = len(arr)

    # Base case when the array has only one element
    if n == 1:
        return arr[0]

    # Recursive case
    mid = n // 2

    # If the middle element is greater than its neighbors, it is a peak element
    if arr[mid] > arr[mid-1] and arr[mid] > arr[mid+1]:
        return arr[mid]

    # If the left element is greater, search in the left half
    elif arr[mid-1] > arr[mid]:
        return find_peak(arr[:mid])

    # If the right element is greater, search in the right half
    else:
        return find_peak(arr[mid+1:])

