class TreeNode:
    def __init__(self, data):
        self.data = data
        self.left = None
        self.right = None

def verticalSum(root):
    sum_map = {} # Hashmap to store vertical sums

    def postorderTraversal(root, dist):
        if root:
            postorderTraversal(root.left, dist - 1)
            postorderTraversal(root.right, dist + 1)
            if dist in sum_map:
                sum_map[dist] += root.data
            else:
                sum_map[dist] = root.data

    def levelOrderTraversal(root):
        queue = []
        queue.append(root)

        while queue:
            node = queue.pop(0)
            dist = node.data

            if node.left:
                node.left.data = dist - 1
                queue.append(node.left)

            if node.right:
                node.right.data = dist + 1
                queue.append(node.right)

    postorderTraversal(root, 0)
    levelOrderTraversal(root)

    return sum_map

