def best_path(graph):
    # Check for invalid input
    if len(graph) == 0:
        return None

    start, goal = None, None
    paths = []

    # Find start and end points in graph
    for city in graph.keys():
        if start is None:
            start = city
        else:
            goal = city

    # Find the best path from the start city to the end city
    current_path = [start]
    visited_nodes = set()
    _best_path(graph, start, goal, current_path, visited_nodes, paths)

    # Find the shortest path in all the paths
    if len(paths) > 0:
        best_path = sorted(paths, key=lambda x: len(x))[0]
        total_distance = 0

        # Calculate the total distance of the best path
        for i in range(len(best_path) - 1):
            total_distance += graph[best_path[i]][best_path[i + 1]]

        return best_path, total_distance
    else:
        return None

# Helper function for finding the best path
def _best_path(graph, s, e, current_path, visited_nodes, paths):
    visited_nodes.add(s)

    if s == e and len(current_path) >= 2:
        paths.append(current_path)
    else:
        if s in graph:
            neighbours = graph[s]
            for neighbour in neighbours.keys():
                if neighbour not in visited_nodes:
                    current_path.append(neighbour)
                    _best_path(graph, neighbour, e, current_path, visited_nodes, paths)
                    current_path.pop()

    visited_nodes.remove(s)

