def safe_merge_sort(arr):
    if len(arr) < 2:
        return arr
    else:
        mid = len(arr) // 2
        left = safe_merge_sort(arr[:mid])
        right = safe_merge_sort(arr[mid:])
        return merge(left, right)

def merge(left, right):
    res = []
    while left and right:
        if left[0] <= right[0]:
            res.append(left.pop(0))
        else:
            res.append(right.pop(0))
    res += left + right
    return res

safe_merge_sort(arr)

