def convert_json_to_xml(json_obj):
    xml = ['<?xml version="1.0" encoding="UTF-8"?>']
    xml.append('<root>')

    def convert_json_to_xml_recursive(json_obj):
        if isinstance(json_obj, dict):
            for k, v in json_obj.items():
                xml.append('<{0}>'.format(k))
                convert_json_to_xml_recursive(v)
                xml.append('</{0}>'.format(k))
        elif isinstance(json_obj, list):
            for item in json_obj:
                xml.append('<item>')
                convert_json_to_xml_recursive(item)
                xml.append('</item>')
        else:
            xml.append(str(json_obj))

    convert_json_to_xml_recursive(json_obj)
    xml.append('</root>')

    return '\n'.join(xml)

